-- Carga puntual de trabajadores externos. No borra empresas ni usuarios.
-- Ejecutar después de respaldar la base productiva.
START TRANSACTION;
ON DUPLICATE KEY UPDATE name=VALUES(name),giro=VALUES(giro);
SELECT id INTO @external_company_id FROM companies WHERE rut='76.271.277-6';
ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),hire_date=VALUES(hire_date),termination_date=VALUES(termination_date),position=VALUES(position),base_salary=VALUES(base_salary),contract_type=VALUES(contract_type),gratification_type=VALUES(gratification_type),health_institution=VALUES(health_institution),isapre_plan_uf=VALUES(isapre_plan_uf),afp=VALUES(afp),meal_allowance=VALUES(meal_allowance),transport_allowance=VALUES(transport_allowance),family_loads=VALUES(family_loads),ccaf=VALUES(ccaf),commune=VALUES(commune),region=VALUES(region),mutual_rate=VALUES(mutual_rate),contributes_afp=VALUES(contributes_afp),status=VALUES(status);
COMMIT;

